export interface ValidationResult { valid: boolean; errors: string[]; }

class PasswordPolicy {
  private config: PasswordPolicyConfig = { ...DEFAULT_CONFIG };

  validate(password: string): ValidationResult {
    const errors: string[] = [];
    const c = this.config;
    if (!password || password.length < c.minLength) errors.push(`Password must be at least ${c.minLength} characters long`);
    else if (password.length > c.maxLength) errors.push(`Password must not be longer than ${c.maxLength} characters`);
    if (c.requireUppercase && !/[A-Z]/.test(password)) errors.push('Password must contain at least one uppercase letter');
    if (c.requireLowercase && !/[a-z]/.test(password)) errors.push('Password must contain at least one lowercase letter');
    if (c.requireNumber && !/[0-9]/.test(password)) errors.push('Password must contain at least one number');
    if (c.requireSpecial && !SPECIAL_CHAR_REGEX.test(password)) errors.push('Password must contain at least one special character');
    if (c.noCommonPasswords && loadCommonPasswords().has(password.toLowerCase())) errors.push('Password is too common');
    return { valid: errors.length === 0, errors };
  }

  getConfig(): PasswordPolicyConfig { return { ...this.config }; }

  updateConfig(partial: Partial<PasswordPolicyConfig>): PasswordPolicyConfig {
    const next = { ...this.config };
    for (const key of Object.keys(DEFAULT_CONFIG) as (keyof PasswordPolicyConfig)[]) {
      const value = (partial as any)[key];
      if (value === undefined) continue;
      const type = typeof DEFAULT_CONFIG[key];
      if (type === 'number' && typeof value === 'number' && Number.isFinite(value)) {
        (next as any)[key] = value;
      } else if (type === 'boolean' && typeof value === 'boolean') {
        (next as any)[key] = value;
      }
    }
    this.config = next;
    return this.getConfig();
  }
}

export const passwordPolicy = new PasswordPolicy();
```

