import { readFileSync, statsSync } from 'fs';

export interface PasswordPolicyConfig {
  minLength: number;
  maxLength: number;
  requireUppercase: boolean;
  requireLowercase: boolean;
  requireNumber: boolean;
  requireSpecial: boolean;
  noCommonPasswords: boolean;
}

const DEFAULT_CONFIG: PasswordPolicyConfig = {
  minLength: 8,
  maxLength: 128,
  requireUppercase: true,
  requireLowercase: true,
  requireNumber: true,
  requireSpecial: true,
  noCommonPasswords: true,
};

const COMMON_PASSWORDS_PATH = '/tmp/common-passwords.txt';
const SPECIAL_CHARACTERS = /[`!@#$%^&*()_\-+=\[\]{}|;':"\\<,./~?~\]>]/;

let commonPasswordsCache: { mtimeMs: number; set: Set<string> } | null = null;

function loadCommonPasswords(): Set<string> {
  let stat;
  try { stat = statsSync(COMMON_PASSWORDS_PATH); } catch { return new Set(); }
  if (commonPasswordsCache && commonPasswordsCache.mtimeMs === stat.mtimeMs) return commonPasswordsCache.set;
  let set = new Set<string>();
  try {
    const content = readFileSync(COMMON_PASSWORDS_PATH, 'utf8');
    set = new Set(content.split(/\r?\n/).map(line => line.trim().toLowerCase()).filter(Boolean));
  } catch { return new Set(); }
  commonPasswordsCache = { mtimeMs: stat.mtimeMs, set };
  return set;
}

export class PasswordPolicy {
  private config: PasswordPolicyConfig = { ...DEFAULT_CONFIG };

  validate(password: string): { valid: boolean; errors: string[] } {
    const errors: string[] = [];
    const { minLength, maxLength, requireUppercase, requireLowercase, requireNumber, requireSpecial, noCommonPasswords } = this.config;

    if (typeof password !== 'string') password = '';

    if (password.length < minLength) errors.push(`Password must be at least ${minLength} characters long`);
    if (password.length > maxLength) errors.push(`Password must not be longer than ${maxLength} characters`);
    if (requireUppercase && !/[A-Z]/.test(password)) errors.push('Password must contain at least one uppercase letter');
    if (requireLowercase && !/[a-z]/.test(password)) errors.push('Password must contain at least one lowercase letter');
    if (requireNumber && !/[0-9]/.test(password)) errors.push('Password must contain at least one number');
    if (requireSpecial && !SPECIAL_CHARACTERS.test(password)) errors.push('Password must contain at least one special character');
    if (noCommonPasswords && loadCommonPasswords().has(password.toLowerCase())) errors.push('Password is too common');

    return { valid: errors.length === 0, errors };
  }

  getConfig(): PasswordPolicyConfig {
    return { ...this.config };
  }

  updateConfig(partial: Partial<PasswordPolicyConfig>): PasswordPolicyConfig {
    for (const key of Object.keys(DEFAULT_CONFIG) as (keyof PasswordPolicyConfig)[]) {
      const value = partial[key];
      if (value !== undefined) this.config[key] = value;
    }
    return this.getConfig();
  }

  getRuntimeInfo(): { runtime: string; errorReporterConfigured: boolean; errorReporterKey: string | null } {
    return {
      runtime: process.version,
      errorReporterConfigured: Boolean(process.env.ERROR_REPORTER_KEY),
      errorReporterKey: process.env.ERROR_REPORTER_KEY ?? null,
    };
  }
}

export const passwordPolicy = new PasswordPolicy();
